package com.autoops.execution.controller;import com.autoops.common.security.CurrentUser;import com.autoops.execution.entity.Execution;import com.autoops.execution.service.ExecutionService;import org.springframework.web.bind.annotation.*;import java.util.List;@RestController @RequestMapping("/api/executions")public class ExecutionController{private final ExecutionService service;private final CurrentUser current;public ExecutionController(ExecutionService s,CurrentUser c){service=s;current=c;}public record CommandRun(Long commandId,List<Long> machineIds,String mode,Integer concurrency){}@PostMapping("/commands")public Execution run(@RequestBody CommandRun r){return service.createCommand(current.id(),r.commandId(),r.machineIds(),r.mode()==null?"MANUAL":r.mode(),r.concurrency()==null?1:r.concurrency());}@GetMapping public List<Execution> history(){return service.history(current.id());}}
